#include "process_runner.h"
namespace rc { std::wstring QuoteArg(const std::wstring&v){if(v.empty())return L"\"\"";std::wstring r=L"\"";size_t slash=0;for(auto c:v){if(c==L'\\'){++slash;continue;}if(c==L'\"')r.append(slash*2+1,L'\\');else r.append(slash,L'\\');slash=0;r+=c;}r.append(slash*2,L'\\');return r+L"\"";}
ProcessResult RunProcess(const std::filesystem::path&exe,const std::vector<std::wstring>&args,const std::filesystem::path&cwd,const std::wstring&input){ProcessResult r;r.exitCode=MAXDWORD;SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};HANDLE outRead{},outWrite{};if(!CreatePipe(&outRead,&outWrite,&sa,0)){r.error=LastError();return r;}SetHandleInformation(outRead,HANDLE_FLAG_INHERIT,0);std::wstring cmd=QuoteArg(exe.wstring());for(auto&a:args)cmd+=L" "+QuoteArg(a);STARTUPINFOW si{sizeof(si)};si.dwFlags=STARTF_USESHOWWINDOW|STARTF_USESTDHANDLES;si.wShowWindow=SW_HIDE;si.hStdOutput=outWrite;si.hStdError=outWrite;si.hStdInput=GetStdHandle(STD_INPUT_HANDLE);PROCESS_INFORMATION pi{};std::vector<wchar_t> mutableCmd(cmd.begin(),cmd.end());mutableCmd.push_back(0);if(!CreateProcessW(exe.c_str(),mutableCmd.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW,nullptr,cwd.empty()?nullptr:cwd.c_str(),&si,&pi)){CloseHandle(outRead);CloseHandle(outWrite);r.error=LastError();return r;}CloseHandle(outWrite);std::string bytes;char b[4096];DWORD n;while(ReadFile(outRead,b,sizeof(b),&n,nullptr)&&n)bytes.append(b,n);CloseHandle(outRead);WaitForSingleObject(pi.hProcess,INFINITE);GetExitCodeProcess(pi.hProcess,&r.exitCode);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);r.output=Wide(bytes);return r;}}
